why-rag-grounding.code:
const log = [
  { q: "what is our refund policy?", from: "parametric" },
  { q: "reverse a string in JavaScript", from: "parametric" },
  { q: "what is the latest price of the Pro plan?", from: "retrieve" },
  { q: "who is our VP of Sales?", from: "parametric" },
];
const factDependent = (q) => /\b(our|policy|refund|price|current|latest|version|who|when)\b/i.test(q);
function audit(entry) {
  const needsGround = factDependent(entry.q);
  return needsGround && entry.from !== "retrieve" ? "RISK" : "ok";
}
let risk = 0;
for (const e of log) {
  const v = audit(e);
  if (v === "RISK") risk++;
  console.log(`${e.q} [${e.from}] -> ${v}`);
}
console.log(`ungrounded risk: ${risk}`);

chunking-strategies.code:
const tokens = ["the", "fee", "is", "fifty", "dollars", "per", "seat"];
const SIZE = 3, STRIDE = 2;
function windows(toks, size, stride) {
  const out = [];
  for (let start = 0; start < toks.length; start += stride) {
    out.push(toks.slice(start, start + size));
    if (start + size >= toks.length) break;
  }
  return out;
}
const ws = windows(tokens, SIZE, STRIDE);
const count = new Map();
for (const w of ws) for (const t of w) count.set(t, (count.get(t) ?? 0) + 1);
for (const w of ws) console.log(w.join(" "));
let hot = tokens[0], hc = 0;
for (const t of tokens) { const c = count.get(t) ?? 0; if (c > hc) { hot = t; hc = c; } }
console.log(`hottest: ${hot} x${hc}`);

embeddings-intuition.code:
const query = [0.9, 0.1, 0.0];
const items = [
  { id: "refund", vec: [0.8, 0.2, 0.0] },
  { id: "money-back", vec: [0.85, 0.15, 0.05] },
  { id: "shipping", vec: [0.1, 0.9, 0.0] },
  { id: "banana", vec: [0.0, 0.1, 0.95] },
];
const d = (a, b) => Math.sqrt(a.reduce((s, x, i) => s + (x - b[i]) ** 2, 0));
function rankByDistance(q, items) {
  return [...items]
    .map((it) => ({ id: it.id, dist: d(q, it.vec) }))
    .sort((a, b) => a.dist - b.dist || a.id.localeCompare(b.id));
}
const ranked = rankByDistance(query, items);
for (const r of ranked) console.log(`${r.id} d=${r.dist.toFixed(3)}`);
console.log(`least related: ${ranked[ranked.length - 1].id}`);

cosine-similarity.code:
const chunks = [
  { id: "a", vec: [1, 0, 0] },
  { id: "b", vec: [2, 0, 1] },
  { id: "c", vec: [0, 3, 0] },
  { id: "d", vec: [4, 0, 2] },
];
const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
const mag = (a) => Math.sqrt(dot(a, a));
const cos = (a, b) => dot(a, b) / (mag(a) * mag(b));
function mostSimilarPair(chunks) {
  const pairs = [];
  for (let i = 0; i < chunks.length; i++)
    for (let j = i + 1; j < chunks.length; j++)
      pairs.push({ key: `${chunks[i].id}-${chunks[j].id}`, cos: cos(chunks[i].vec, chunks[j].vec) });
  return pairs.sort((a, b) => b.cos - a.cos || a.key.localeCompare(b.key));
}
const ranked = mostSimilarPair(chunks);
for (const p of ranked) console.log(`${p.key} cos=${p.cos.toFixed(3)}`);
console.log(`dedup: ${ranked[0].key.replace("-", ",")}`);

vector-stores-upsert.code:
const store = new Map();
for (const r of [
  { id: "policy#0", text: "Refunds within 14 days." },
  { id: "policy#1", text: "Fee is $50." },
  { id: "faq#0", text: "We ship worldwide." },
  { id: "policy#2", text: "Contact support." },
]) store.set(r.id, r);
function purge(store, source) {
  const prefix = `${source}#`;
  let removed = 0;
  for (const id of [...store.keys()]) if (id.startsWith(prefix)) { store.delete(id); removed++; }
  return removed;
}
console.log(`before: ${store.size}`);
const removed = purge(store, "policy");
console.log(`removed: ${removed}`);
console.log(`after: ${store.size}`);

