top-k-thresholds.code:
const TAU = 0.35, MIN = 2;
const many = [ { id: "a", score: 0.82 }, { id: "b", score: 0.40 }, { id: "c", score: 0.12 } ];
const lone = [ { id: "x", score: 0.77 }, { id: "y", score: 0.20 }, { id: "z", score: 0.05 } ];
function decide(cands) {
  const kept = [...cands]
    .filter((c) => c.score >= TAU)
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
  if (kept.length < MIN) return { verdict: "refuse", ids: [] };
  return { verdict: "ground", ids: kept.map((c) => c.id) };
}
for (const [name, set] of [["many", many], ["lone", lone]]) {
  const r = decide(set);
  console.log(`${name}: ${r.verdict} ${r.ids.length ? r.ids.join(",") : "-"}`);
}

hybrid-search.code:
const lexical = ["d3", "d2", "d1"];
const vector = ["d2", "d1", "d4"];
const K = 60;
function fuse(lists, k) {
  const score = new Map();
  for (const list of lists) list.forEach((id, i) => score.set(id, (score.get(id) ?? 0) + 1 / (k + (i + 1))));
  return [...score.entries()]
    .map(([id, s]) => ({ id, score: s }))
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}
const fused = fuse([lexical, vector], K);
for (const r of fused) console.log(`${r.id}=${r.score.toFixed(5)}`);
const changed = lexical[0] !== fused[0].id ? "yes" : "no";
console.log(`lexical#1: ${lexical[0]}  fused#1: ${fused[0].id}  changed: ${changed}`);

query-rewriting.code:
const glossary = { "SLA": "service level agreement", "refund": "money-back guarantee" };
const queries = [
  "what is the SLA?",
  "how do I get a refund?",
  "reset my password",
];
function expand(query, glossary) {
  let out = query;
  for (const [alias, canonical] of Object.entries(glossary)) {
    out = out.replace(new RegExp(`\\b${alias}\\b`, "gi"), canonical);
  }
  return out;
}
for (const q of queries) console.log(`${q} -> ${expand(q, glossary)}`);

reranking.code:
const query = "refund window policy";
const stage1 = [
  { id: "a", text: "shipping and delivery times" },
  { id: "b", text: "our refund policy and refund window" },
  { id: "c", text: "policy for enterprise plans" },
  { id: "d", text: "password reset instructions" },
];
const K = 2;
function rerank(query, docs) {
  const terms = query.toLowerCase().split(/\s+/);
  return [...docs]
    .map((d) => {
      const words = new Set(d.text.toLowerCase().split(/\s+/));
      const rel = terms.filter((t) => words.has(t)).length;
      return { id: d.id, rel };
    })
    .sort((a, b) => b.rel - a.rel || a.id.localeCompare(b.id))
    .slice(0, K)
    .map((x) => x.id);
}
const top3 = stage1.slice(0, 3);
console.log(`stage1: ${top3.map((d) => d.id).join(",")}`);
console.log(`reranked: ${rerank(query, top3).join(",")}`);

rag-cost-latency.code:
const tokensPerChunk = 200, inputPer1k = 0.50;
const queriesPerDay = 1000, days = 30, budget = 20000;
function monthlyCost(k) {
  const perQuery = (k * tokensPerChunk / 1000) * inputPer1k;
  return perQuery * queriesPerDay * days;
}
for (const k of [3, 10]) {
  const c = monthlyCost(k);
  console.log(`k=${k}: $${c.toFixed(2)} ${c > budget ? "OVER" : "under"}`);
}
